def semver_sort(versions):
    def parse(v):
        core = v
        pre = None
        if '+' in core:
            core, _ = core.split('+', 1)
        if '-' in core:
            core, pre = core.split('-', 1)
        major, minor, patch = (int(x) for x in core.split('.'))
        pre_ids = pre.split('.') if pre is not None else None
        return (major, minor, patch, pre_ids)

    def id_key(ident):
        if ident.isdigit():
            return (0, int(ident))
        else:
            return (1, ident)

    def cmp_key(v):
        major, minor, patch, pre_ids = parse(v)
        if pre_ids is None:
            has_pre = 1
            pre_key = ()
        else:
            has_pre = 0
            pre_key = tuple(id_key(i) for i in pre_ids)
        return (major, minor, patch, has_pre, pre_key)

    return sorted(versions, key=cmp_key)

